import java.io.*;
import java.util.*;

public class Main {
    static class FastScanner {
        BufferedReader br;
        StringTokenizer st;

        FastScanner() {
            br = new BufferedReader(new InputStreamReader(System.in));
        }

        String next() throws IOException {
            while (st == null || !st.hasMoreTokens()) {
                String line = br.readLine();
                if (line == null) return null;
                st = new StringTokenizer(line);
            }
            return st.nextToken();
        }

        int nextInt() throws IOException {
            return Integer.parseInt(next());
        }
    }

    public static void main(String[] args) throws IOException {
        FastScanner fs = new FastScanner();
        int N = fs.nextInt();

        long[] order = new long[N];
        for (int i = 0; i < N; i++) {
            int h = fs.nextInt();
            order[i] = ((long) h << 32) | i;
        }

        Arrays.sort(order);

        boolean[] active = new boolean[N];
        int current = 0;
        int max = 0;
        int idx = N - 1;

        while (idx >= 0) {
            int h = (int) (order[idx] >>> 32);

            if (current > max) max = current;

            while (idx >= 0 && (int) (order[idx] >>> 32) == h) {
                int pos = (int) (order[idx] & 0xffffffffL);

                boolean left = pos > 0 && active[pos - 1];
                boolean right = pos + 1 < N && active[pos + 1];

                if (left && right) {
                    current--;
                } else if (!left && !right) {
                    current++;
                }

                active[pos] = true;
                idx--;
            }

            if (current > max) max = current;
        }

        System.out.println(max + 1);
    }
}
